const job=$json.job??$json;
const interaction=job.message?.interaction??null;
const empty=()=>({service_id:null,professional_id:null,date:null,date_until:null,period:null,time:null,time_from:null,time_until:null,option_number:null,appointment_id:null,allow_professional_fallback:false,marketing_opt_in:null,waitlist_id:null,slot_offer_id:null});
let structured=null;
if(interaction?.action==='SELECT_SLOT' && interaction.slot_offer_id && Number.isInteger(interaction.option_number)){
  structured={kind:'BUSINESS_ACTION',intent:'SELECT_SLOT',action:'SELECT_SLOT',arguments:{...empty(),option_number:interaction.option_number,slot_offer_id:interaction.slot_offer_id},missing_information:[],customer_meaning:`Cliente selecionou a opção ${interaction.option_number} da oferta apresentada.`,direct_response:null,confidence:1};
}else if(interaction?.action==='REBOOK_APPOINTMENT' && interaction.appointment_id){
  structured={kind:'BUSINESS_ACTION',intent:'REBOOK_APPOINTMENT',action:'REBOOK_APPOINTMENT',arguments:{...empty(),appointment_id:interaction.appointment_id},missing_information:[],customer_meaning:'Cliente pediu novos horários para o agendamento cancelado.',direct_response:null,confidence:1};
}
return {json:{job,command_source:structured?'STRUCTURED':'AI',structured_command:structured}};
